#!/usr/bin/env node
// Prepends a "generated" header to the bundled docs/04-api/openapi.yaml.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const file = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'openapi.yaml');
const body = fs.readFileSync(file, 'utf8').replace(/^# GENERATED[^\n]*\n(#[^\n]*\n)*/, '');
const header = [
  '# GENERATED by `npm run bundle` in docs/04-api from docs/04-api/src (Redocly bundle). DO NOT EDIT BY HAND.',
  '# The contract is the law (CLAUDE.md). Only the solution-architect changes docs/04-api/src, with an ADR after approval.',
  '',
].join('\n');
fs.writeFileSync(file, header + body);
console.log('stamp-bundle: header written to openapi.yaml');
